noncomputable def VTask.piEquivPiSubtypeProd {α : Type u_9} (p : α → Prop) (β : α → Type u_10) [DecidablePred p] :
    ((i : α) → β i) ≃ ((i : { x // p x }) → β ↑i) × ((i : { x // ¬p x }) → β ↑i) :=
  let positive := { x // p x }
  let negative := { x // ¬p x }
  let f (f' : (i : positive) → β i.val) (f'' : (i : negative) → β i.val) : (i : α) → β i :=
    λ i, match i with
         | ⟨_, hp⟩ => f' ⟨i, hp⟩
         | ⟨_, hn⟩ => f'' ⟨i, hn⟩
  let g (f' : (i : α) → β i) : ((i : positive) → β i.val) × ((i : negative) → β i.val) :=
    (λ i, f' i, λ i, f' i)
  Equiv.mk f g (by simp) (by simp)
